`timescale 1ns/1ps
// Basys 3 top level - generated by scripts/make_experiments.py
module top_basys3 (
    input  wire        clk,                    // 100 MHz
    input  wire        btnC, btnU, btnL, btnR, // btnC = reset
    input  wire [15:0] sw,
    output wire [15:0] led,
    output wire [3:0]  an,
    output wire [6:0]  seg
);
    wire rst = btnC;
    wire en;   // one model step every 1/20 s, slow enough to watch
    step_tick #(.STEP_HZ(20)) u_tick (.clk(clk), .rst(rst), .tick(en));
    // pre-synaptic spikes: press btnU, or sw[0] = random spike train (rate from sw[3:1])
    wire press;  btn_pulse u_b (.clk(clk), .rst(rst), .tick(en), .btn(btnU), .pulse(press));
    wire [15:0] rnd;  lfsr16 u_r (.clk(clk), .rst(rst), .en(en), .q(rnd));
    wire pre = press | (en & sw[0] & (rnd < {sw[3:1], 13'd0}));
    wire signed [31:0] s, i_syn;
    alpha_synapse u_s (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .s(s), .i_syn(i_syn));
    wire spike_led;
    pulse_stretch u_ps (.clk(clk), .rst(rst), .in(pre), .out(spike_led));
    wire signed [31:0] bar_val = i_syn >>> 8;
    bar15 #(.FULL(5)) u_bar (.val(bar_val), .leds(led[14:0]));
    assign led[15] = spike_led;
    wire signed [31:0] num = i_syn >>> 8;
    seg7_signed u_seg (.clk(clk), .value(num[15:0]), .an(an), .seg(seg));
endmodule
